-- Structured strength prescriptions.
--
-- A strength session used to be prose: planned_session_versions.details held
-- "Lat Pulldown — 3 × 8–12" and nothing a client could render or log against.
-- This gives a strength version an ordered, typed list of exercises, delivered through the same
-- athlete_plan_feed that already carries running components, so FORM running and Forge strength
-- are two projections of one athlete / assignment / version system.
--
-- Rules this migration holds:
--   * Exercises belong to an immutable VERSION, never to the session. A completed workout can
--     always point at the exact prescription it was performed against, even after a revision.
--   * Append-only, like the version it hangs from. A revision writes a new version with its own
--     exercises; nothing edits a prescription in place.
--   * Nothing is invented. Rest, cue and substitutions stay null unless authored; the authored
--     instruction is kept losslessly in `instruction`.
--   * planned_session_versions.details is untouched. It remains the readable fallback.
--   * The feed change is additive. A session with no structured exercises is byte-for-byte what
--     it was; only a session that has them gains an "exercises" key. Clients that do not know
--     about the key keep decoding.
--   * This stores prescription only. Where an athlete is (opened, completed, current week) is
--     progress, and it is never written here.
begin;

create table public.planned_session_exercises (
  id uuid primary key default gen_random_uuid(),
  athlete_id uuid not null references public.athletes(id) on delete cascade,
  version_id uuid not null references public.planned_session_versions(id) on delete cascade,
  -- The order the athlete meets them in.
  position smallint not null check (position > 0),
  -- Stable identity, so history and progression follow the movement. The name is for display.
  movement_id text not null check (movement_id ~ '^[a-z0-9_]+$' and length(movement_id) <= 120),
  movement_name text not null check (length(btrim(movement_name)) between 1 and 200),
  sets smallint not null check (sets between 1 and 20),
  -- Repetition work: a range, which may be a single number (8 to 8).
  rep_low smallint check (rep_low is null or rep_low between 1 and 200),
  rep_high smallint check (rep_high is null or rep_high between 1 and 200),
  -- What a counted target counts, when it is not plain repetitions ("out-and-back cycles").
  -- Null means repetitions. Kept as authored text; the server does not interpret it.
  rep_unit text check (rep_unit is null or length(btrim(rep_unit)) between 1 and 60),
  -- Timed work: seconds, optionally a range. Exactly one of the two kinds per exercise.
  target_seconds integer check (target_seconds is null or target_seconds between 1 and 7200),
  target_seconds_high integer check (target_seconds_high is null or target_seconds_high between 1 and 7200),
  laterality text not null check (laterality in ('bilateral', 'per_side')),
  -- How the coach wrote "per side": "side" or "leg". Display only; kept so the authored text
  -- reproduces exactly. Present exactly when the exercise is per side.
  side_word text check (side_word is null or side_word in ('side', 'leg')),
  rest_seconds integer check (rest_seconds is null or rest_seconds between 0 and 1200),
  cue text check (cue is null or length(cue) <= 500),
  -- The authored instruction for this exercise, kept losslessly as written ("Brace on the bench
  -- and draw your elbow toward your hip without twisting."). The source does not separate a
  -- cue from a coach note, so neither is guessed: this is the whole authored text.
  instruction text check (instruction is null or length(instruction) <= 2000),
  -- [{"movement_id": "...", "movement_name": "..."}], authored substitutions only.
  substitutions jsonb check (substitutions is null or jsonb_typeof(substitutions) = 'array'),
  created_at timestamptz not null default now(),
  unique (version_id, position),
  constraint exercise_has_one_measure check ((rep_low is not null) <> (target_seconds is not null)),
  constraint exercise_reps_are_a_range check (
    (rep_low is null and rep_high is null) or (rep_low is not null and rep_high is not null and rep_low <= rep_high)),
  constraint exercise_unit_needs_a_count check (rep_unit is null or rep_low is not null),
  constraint exercise_side_word_matches_laterality check ((laterality = 'per_side') = (side_word is not null)),
  constraint exercise_seconds_are_a_range check (
    target_seconds_high is null or (target_seconds is not null and target_seconds_high >= target_seconds))
);

create index planned_session_exercises_version_idx
  on public.planned_session_exercises (version_id, position);
create index planned_session_exercises_athlete_movement_idx
  on public.planned_session_exercises (athlete_id, movement_id);

alter table public.planned_session_exercises enable row level security;
revoke all on public.planned_session_exercises from public, anon, authenticated;
grant select, insert on public.planned_session_exercises to authenticated;

create policy exercises_member_read on public.planned_session_exercises
  for select to authenticated using (public.can_read_athlete(athlete_id));
create policy exercises_coach_insert on public.planned_session_exercises
  for insert to authenticated with check (public.is_coach_member(athlete_id));

-- An exercise row must name the same athlete as the version it hangs from. RLS alone cannot say
-- this, and a mismatched row would let one athlete's feed or history read another's prescription.
create function public.exercise_matches_version_athlete()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  if not exists (
    select 1 from public.planned_session_versions v
     where v.id = new.version_id and v.athlete_id = new.athlete_id) then
    raise exception 'An exercise must belong to a version of the same athlete';
  end if;
  return new;
end;
$$;

create trigger planned_session_exercises_same_athlete
  before insert on public.planned_session_exercises
  for each row execute function public.exercise_matches_version_athlete();

-- Same append-only guard the version itself carries.
create trigger planned_session_exercises_immutable
  before update or delete on public.planned_session_exercises
  for each row execute function public.prevent_immutable_change();

-- A trigger function is invoked by its trigger; it must not also be a client-callable RPC.
revoke all on function public.exercise_matches_version_athlete() from public, anon, authenticated;

comment on table public.planned_session_exercises is
  'The ordered, typed strength prescription of one immutable session version. Prescription only: progress and performance live elsewhere.';
comment on column public.planned_session_exercises.movement_id is
  'Stable identity of the movement. History, progression and substitution follow this, not the display name.';
comment on column public.planned_session_exercises.instruction is
  'The authored instruction, losslessly. Also the text after " · " in planned_session_versions.details.';
comment on column public.planned_session_exercises.rest_seconds is
  'Null means the coach did not author a rest. The client applies its own default; the server never invents one.';

-- ── The feed: additive ────────────────────────────────────────────────────────
--
-- Whatever athlete_plan_feed is today (it is a wrapper over athlete_plan_feed_impl, which later
-- migrations patch in place) is kept as-is under a new name, and the public entry point wraps it.
-- Nothing about the existing function's text is rewritten, so a difference between this
-- repository and a live definition cannot be silently overwritten here.
do $$
begin
  if not exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace
                  where n.nspname = 'public' and p.proname = 'athlete_plan_feed_before_exercises') then
    alter function public.athlete_plan_feed(uuid) rename to athlete_plan_feed_before_exercises;
  end if;
end $$;

revoke all on function public.athlete_plan_feed_before_exercises(uuid) from public, anon, authenticated;

create or replace function public.athlete_plan_feed(p_athlete_id uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
  payload jsonb;
begin
  -- Everything the feed already enforces (membership, the sync switch, what it may carry) runs
  -- first and unchanged. Exercises are only ever added to sessions of the athlete it authorised.
  payload := public.athlete_plan_feed_before_exercises(p_athlete_id);
  if payload is null or jsonb_typeof(payload->'sessions') is distinct from 'array' then
    return payload;
  end if;

  return jsonb_set(payload, '{sessions}', coalesce((
    select jsonb_agg(
             case when ex.exercises is null then s.value
                  else s.value || jsonb_build_object('exercises', ex.exercises) end
             order by s.ord)
      from jsonb_array_elements(payload->'sessions') with ordinality as s(value, ord)
      left join lateral (
        select jsonb_agg(jsonb_build_object(
                 'position', e.position,
                 'movement_id', e.movement_id,
                 'movement_name', e.movement_name,
                 'sets', e.sets,
                 'rep_low', e.rep_low, 'rep_high', e.rep_high, 'rep_unit', e.rep_unit,
                 'target_seconds', e.target_seconds, 'target_seconds_high', e.target_seconds_high,
                 'laterality', e.laterality, 'side_word', e.side_word,
                 'rest_seconds', e.rest_seconds,
                 'cue', e.cue,
                 'instruction', e.instruction,
                 'substitutions', e.substitutions)
               order by e.position) as exercises
          from public.planned_session_exercises e
         where e.athlete_id = p_athlete_id
           and e.version_id = (s.value->'version'->>'id')::uuid) ex on true), '[]'::jsonb));
end $$;

revoke all on function public.athlete_plan_feed(uuid) from public, anon;
grant execute on function public.athlete_plan_feed(uuid) to authenticated;

comment on function public.athlete_plan_feed(uuid) is
  'The athlete''s own dated plan. Sessions whose current version has structured strength exercises carry them under "exercises"; every other session is unchanged.';

-- ── Backfill ──────────────────────────────────────────────────────────────────
--
-- Attaches structured exercises to the athlete's CURRENT version of a session, but only when
-- that version's readable details are exactly the text the same exercises would produce. If a
-- version was revised since, or says something else, it is reported and left alone: the
-- structured rows must describe the prescription the version actually carries, never a guess.
-- Idempotent: a version that already has exercises is never touched. Owner-only; no client can
-- call it.
create function public.backfill_structured_strength(p_athlete_id uuid, p_sessions jsonb)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  s jsonb;
  e jsonb;
  v_session uuid;
  v_version record;
  filled integer := 0;
  already integer := 0;
  skipped jsonb := '[]'::jsonb;
begin
  for s in select value from jsonb_array_elements(p_sessions)
  loop
    select ps.id into v_session
      from public.planned_sessions ps
     where ps.athlete_id = p_athlete_id and ps.scheduled_on = (s->>'scheduled_on')::date
     limit 1;
    if v_session is null then
      skipped := skipped || jsonb_build_array(jsonb_build_object('scheduled_on', s->>'scheduled_on', 'reason', 'no_session'));
      continue;
    end if;

    select v.id, v.shape, v.details into v_version
      from public.planned_session_versions v
     where v.planned_session_id = v_session
     order by v.version_number desc limit 1;

    if v_version.shape is distinct from 'strength' then
      skipped := skipped || jsonb_build_array(jsonb_build_object('scheduled_on', s->>'scheduled_on', 'reason', 'not_strength'));
    elsif exists (select 1 from public.planned_session_exercises x where x.version_id = v_version.id) then
      already := already + 1;
    elsif v_version.details is distinct from (s->>'details') then
      skipped := skipped || jsonb_build_array(jsonb_build_object('scheduled_on', s->>'scheduled_on', 'reason', 'details_differ'));
    else
      for e in select value from jsonb_array_elements(s->'exercises')
      loop
        insert into public.planned_session_exercises (
          athlete_id, version_id, position, movement_id, movement_name, sets,
          rep_low, rep_high, rep_unit, target_seconds, target_seconds_high, laterality, side_word, instruction
        ) values (
          p_athlete_id, v_version.id, (e->>'position')::smallint, e->>'movement_id', e->>'movement_name',
          (e->>'sets')::smallint,
          (e->>'rep_low')::smallint, (e->>'rep_high')::smallint, e->>'rep_unit',
          (e->>'target_seconds')::integer, (e->>'target_seconds_high')::integer,
          e->>'laterality', e->>'side_word', e->>'instruction');
      end loop;
      filled := filled + 1;
    end if;
  end loop;
  return jsonb_build_object('filled', filled, 'already', already, 'skipped', skipped);
end $$;

revoke all on function public.backfill_structured_strength(uuid, jsonb) from public, anon, authenticated;

